def lps(s):
    n = len(s)
    if n == 0:
        return 0

    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(i - 1, -1, -1):
            if s[i - 1] == s[j]:
                dp[i][j] = dp[i - 1][j + 1] + 2
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j + 1])

    return dp[n][0]
